(async()=>{'use strict';const C=LifelineHumanV12,m=await(await fetch('manifest.json?audit=2')).json(),$=id=>document.getElementById(id),art=C.create(m);const labels={infant:'Младенец',toddler:'Малыш',child:'Ребёнок',teen:'Подросток',adult:'Взрослый',elder:'Пожилой'},hairLabels={short:'Короткие кудри',bob:'Каре',compact_coils:'Плотные кудри',tousled:'Короткие волнистые',long_straight:'Прямые до плеч',ponytail:'Хвост',bun:'Пучок',braids:'Две косы',baby_tuft:'Пушок',long_sleek:'Длинные прямые',long_curly:'Длинные кудрявые',single_braid:'Одна коса'};let token=0;for(const [age]of C.AGE_GROUPS){const o=document.createElement('option');o.value=age;o.textContent=labels[age];$('age').append(o)}$('age').value='child';
async function render(){const t=++token,age=$('age').value,sex=$('sex').value,months=Math.max(C.AGE_GROUPS.find(a=>a[0]===age)[1],age==='infant'?6:0),profile=C.profileFor(months,sex),p=m.profiles[profile],styles=Object.keys(m.heads[age+'_'+sex+'_0'].hairLayers);$('grid').replaceChildren();$('grid').dataset.ready='false';let count=0;$('status').textContent='Собираю…';for(const name of styles){for(let face=0;face<4;face++){const c={...C.preset('slavic',1,months,sex),profile,face,hair:name,skin:1,hairColor:Number($('color').value),outfit:0,pose:p.poses[0],happiness:100,energy:100},im=await art.actor(c);if(t!==token)return;const d=p.outfits['0'].poses[c.pose],scale=p.headHeight/280,[nx,ny]=d.neckAnchor,canvas=document.createElement('canvas');canvas.width=360;canvas.height=400;const ctx=canvas.getContext('2d'),hd=m.heads[age+'_'+sex+'_'+face],rects=Object.values(hd.hairLayers[name].authoredParts).flat().map(p=>p.rect).concat([[hd.bounds[0],hd.bounds[1],hd.bounds[2]-hd.bounds[0],hd.bounds[3]-hd.bounds[1]]]),lx=Math.min(...rects.map(r=>r[0]))-12,ly=Math.min(...rects.map(r=>r[1]))-12,rx=Math.max(...rects.map(r=>r[0]+r[2]))+12,by=Math.max(...rects.map(r=>r[1]+r[3]),hd.headAnchor[1]+110)+12,box=[nx+(lx-hd.headAnchor[0])*scale,ny+(ly-hd.headAnchor[1])*scale,(rx-lx)*scale,(by-ly)*scale],fit=Math.min(360/box[2],400/box[3]);ctx.drawImage(im,...box,(360-box[2]*fit)/2,(400-box[3]*fit)/2,box[2]*fit,box[3]*fit);const f=document.createElement('figure'),cap=document.createElement('figcaption');cap.textContent=hairLabels[name]+' · лицо '+(face+1);f.dataset.hair=name;f.dataset.face=face;f.append(cap,canvas);$('grid').append(f);count++;}}$('grid').dataset.ready='true';$('grid').dataset.group=age+'_'+sex;$('grid').dataset.count=count;$('status').textContent='Готово: '+count+' сочетаний · '+labels[age]+' · '+(sex==='female'?'женский':'мужской');}
for(const id of ['age','sex','color'])$(id).onchange=()=>render().catch(showError);function showError(e){$('status').textContent='Ошибка: '+e.message;console.error(e)}await render();})().catch(e=>{document.getElementById('status').textContent='Ошибка: '+e.message;console.error(e)});
